import React, { useState } from 'react';
import { Outlet, NavLink, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';


const AdminLayout = () => {
  const { currentUser, logout } = useAuth();
  const navigate = useNavigate();
  const [sidebarOpen, setSidebarOpen] = useState(true);

  const handleLogout = () => { logout(); navigate('/'); };

  const links = [
    { to: '/admin/dashboard', icon: 'bi-speedometer2', label: 'Dashboard' },
    { to: '/admin/users', icon: 'bi-people', label: 'Users' },
    { to: '/admin/destinations', icon: 'bi-geo-alt', label: 'Destinations' },
    { to: '/admin/packages', icon: 'bi-briefcase', label: 'Packages' },
    { to: '/admin/hotels', icon: 'bi-building', label: 'Hotels & Villas' },
    { to: '/admin/enquiries', icon: 'bi-envelope', label: 'Enquiries' },
    { to: '/admin/reviews', icon: 'bi-star', label: 'Reviews' },
    { to: '/admin/gallery', icon: 'bi-images', label: 'Gallery' },
  ];

  return (
    <div className="d-flex">
      {/* Sidebar */}
      <div style={{
        background: '#12212E', minHeight: '100vh', width: sidebarOpen ? '260px' : '70px',
        position: 'fixed', left: 0, top: 0, zIndex: 1000, transition: 'width 0.3s ease',
        display: 'flex', flexDirection: 'column'
      }}>
        {/* Logo */}
        <div style={{ padding: '20px 16px', borderBottom: '1px solid rgba(255,255,255,0.1)' }}>
          <div className="d-flex align-items-center gap-2">
            <div style={{
              width: 36, height: 36, borderRadius: 8,
              background: 'linear-gradient(135deg, #307082, #EA9940)',
              display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0
            }}>
              <i className="bi bi-compass text-white" style={{ fontSize: '1.1rem' }}></i>
            </div>
            {sidebarOpen && (
              <span style={{ fontFamily: 'Poppins', fontWeight: 800, color: 'white', fontSize: '1.2rem' }}>
                Trip<em style={{ color: '#EA9940', fontStyle: 'normal' }}>Nova</em>
              </span>
            )}
          </div>
        </div>

        {/* Nav Links */}
        <nav style={{ flex: 1, padding: '12px 0', overflowY: 'auto' }}>
          {links.map(link => (
            <NavLink key={link.to} to={link.to} style={({ isActive }) => ({
              display: 'flex', alignItems: 'center', gap: 12,
              padding: '12px 20px', color: isActive ? 'white' : 'rgba(255,255,255,0.65)',
              textDecoration: 'none', fontFamily: 'Inter', fontSize: '0.88rem', fontWeight: 500,
              borderLeft: isActive ? '3px solid #EA9940' : '3px solid transparent',
              background: isActive ? 'rgba(255,255,255,0.08)' : 'transparent',
              transition: 'all 0.2s', whiteSpace: 'nowrap', overflow: 'hidden'
            })}>
              <i className={`bi ${link.icon}`} style={{ fontSize: '1.1rem', flexShrink: 0 }}></i>
              {sidebarOpen && link.label}
            </NavLink>
          ))}
        </nav>

        {/* Bottom */}
        <div style={{ padding: '16px', borderTop: '1px solid rgba(255,255,255,0.1)' }}>
          <NavLink to="/home" style={{ display: 'flex', alignItems: 'center', gap: 10, color: 'rgba(255,255,255,0.65)', textDecoration: 'none', fontSize: '0.85rem', marginBottom: 8 }}>
            <i className="bi bi-house" style={{ flexShrink: 0 }}></i>
            {sidebarOpen && 'Back to Site'}
          </NavLink>
          <button onClick={handleLogout} style={{
            display: 'flex', alignItems: 'center', gap: 10, color: '#EA9940',
            background: 'none', border: 'none', cursor: 'pointer', fontSize: '0.85rem', padding: 0
          }}>
            <i className="bi bi-box-arrow-right" style={{ flexShrink: 0 }}></i>
            {sidebarOpen && 'Logout'}
          </button>
        </div>
      </div>

      {/* Main Content */}
      <div style={{ marginLeft: sidebarOpen ? '260px' : '70px', flex: 1, minHeight: '100vh', background: '#f8f9fa', transition: 'margin-left 0.3s ease' }}>
        {/* Top Bar */}
        <div style={{
          background: 'white', padding: '14px 24px', borderBottom: '1px solid #e0e0e0',
          display: 'flex', alignItems: 'center', justifyContent: 'space-between',
          position: 'sticky', top: 0, zIndex: 100, boxShadow: '0 2px 8px rgba(0,0,0,0.06)'
        }}>
          <button onClick={() => setSidebarOpen(!sidebarOpen)} style={{ background: 'none', border: 'none', cursor: 'pointer', fontSize: '1.2rem', color: '#12212E' }}>
            <i className={`bi ${sidebarOpen ? 'bi-layout-sidebar' : 'bi-layout-sidebar-reverse'}`}></i>
          </button>
          <div className="d-flex align-items-center gap-3">
            <span style={{ fontFamily: 'Inter', fontSize: '0.9rem', color: '#666' }}>
              Welcome, <strong style={{ color: '#12212E' }}>{currentUser?.name}</strong>
            </span>
            <div style={{
              width: 36, height: 36, borderRadius: '50%',
              background: 'linear-gradient(135deg, #307082, #EA9940)',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              color: 'white', fontWeight: 700, fontSize: '0.85rem', fontFamily: 'Poppins'
            }}>
              {currentUser?.name?.charAt(0).toUpperCase()}
            </div>
          </div>
        </div>

        {/* Page Content */}
        <div style={{ padding: '28px' }}>
          <Outlet />
        </div>
      </div>
    </div>
  );
};

export default AdminLayout;
